select * from (select case when balance >= 68000 then 'high' when balance >= 24000 then 'mid' else 'low' end as balance_bucket, max(balance) as max_balance, round((100 * sum(case when status = 'OPEN' then 1 else 0 end)) / count(*), 1) as pct_open from accounts group by case when balance >= 68000 then 'high' when balance >= 24000 then 'mid' else 'low' end) as s where pct_open < 69;
